// Descriptor publishes the local-file package source and its describe command.
func Descriptor() ohrats_rc_plugin_types.Descriptor {
	return ohrats_rc_plugin_types.Descriptor{
		Id:      "ohrats:local-source",
		Version: "0.1.0",
		Provides: []ohrats_rc_plugin_types.Service{{
			Name:     "ohrats:rc-plugin/package-source",
			Version:  "0.1.0",
			Priority: 100,
			Keys:     []string{"file"},
		}},
		Requires: []ohrats_rc_plugin_types.Requirement{},
		Commands: []ohrats_rc_plugin_types.Command{{
			Name:    "source-file",
			Summary: "Describe the local-file package source",
			Usage:   "rc source-file",
		}},
	}
}

// Activate has no component-local setup.
func Activate() witTypes.Result[witTypes.Unit, string] {
	return witTypes.Ok[witTypes.Unit, string](witTypes.Unit{})
}

// Deactivate has no component-local teardown.
func Deactivate() {}

// Invoke describes the local-file source syntax.
func Invoke(command string, _ []string) witTypes.Result[uint32, string] {
	if command != "source-file" {
		return witTypes.Err[uint32, string](fmt.Sprintf("unsupported command %q", command))
	}
	fmt.Println("file:<path> or a direct ./relative/path.wasm")
	return witTypes.Ok[uint32, string](0)
}
